SELECT managed_resource.RESOURCE_ID,managed_resource.USER_NAME,managed_resource.STATUS,managed_resource.STATUS_MESSAGE,managed_resource.SAFE_PUBLICATION,managed_resource.RULE_TEMPLATE_ID,managed_resource.CREATED_AT,managed_resource.COMMENTS,managed_resource.EXPIRED_AT,managed_resource.RESOURCE_MARK_ID,managed_resource.INSTANCE_ID,managed_resource.RESOURCE_NAME,managed_resource.PAY_MODE,resource_mark.mark_name,resource_mark.color,rules_template.name,common_resource.src_instance_id,common_resource.database_kind,common_resource.source_type,common_resource.ip,common_resource.port FROM managed_resource LEFT JOIN common_resource ON (managed_resource.resource_id=common_resource.resource_id) LEFT JOIN resource_mark ON (managed_resource.resource_mark_id = resource_mark.id) LEFT JOIN rules_template ON (managed_resource.rule_template_id = rules_template.template_id) ORDER BY src_instance_id ASC